import{_ as e,o as a,c as s,ag as r}from"./chunks/framework.DqVSm8kp.js";const m=JSON.parse('{"title":"Educators Kit","description":"","frontmatter":{},"headers":[],"relativePath":"en/community/educators/index.md","filePath":"en/community/educators/index.md"}'),n={name:"en/community/educators/index.md"};function i(o,t,d,l,h,u){return a(),s("div",null,[...t[0]||(t[0]=[r(`<h1 id="educators-kit" tabindex="-1">Educators Kit <a class="header-anchor" href="#educators-kit" aria-label="Permalink to &quot;Educators Kit&quot;">​</a></h1><div style="background:linear-gradient(135deg, rgba(168,85,247,0.08), rgba(124,58,237,0.04));border-left:4px solid #a855f7;padding:1rem 1.5rem;border-radius:0 8px 8px 0;margin-bottom:2rem;"><p><strong>A progressive curriculum for teaching AI/ML with local models.</strong></p><p>8 modules. From &quot;What is a token?&quot; to &quot;I contributed to real AI research.&quot; Free. Local. Visual. No cloud costs. No student API keys.</p></div><h2 id="why-llmxray-for-teaching" tabindex="-1">Why LLMxRay for Teaching? <a class="header-anchor" href="#why-llmxray-for-teaching" aria-label="Permalink to &quot;Why LLMxRay for Teaching?&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Advantage</th><th>Details</th></tr></thead><tbody><tr><td><strong>Free</strong></td><td>No API keys, no cloud costs, no student subscriptions. Zero budget required.</td></tr><tr><td><strong>Local</strong></td><td>All data stays on the student&#39;s machine. No privacy concerns, no institutional data policies.</td></tr><tr><td><strong>Visual</strong></td><td>Students see tokens stream in real time, watch confidence coloring, explore reasoning chains. Abstract concepts become tangible.</td></tr><tr><td><strong>Safe</strong></td><td>No risk of students accidentally running up cloud bills or exposing sensitive data.</td></tr><tr><td><strong>Cross-platform</strong></td><td>Runs on Windows, macOS, and Linux. Deploy via <code>npx llmxray</code>, Docker, or git clone.</td></tr><tr><td><strong>Research-ready</strong></td><td>Every experiment is reproducible. Students contribute real findings to the open-source community.</td></tr></tbody></table><h2 id="course-integration" tabindex="-1">Course Integration <a class="header-anchor" href="#course-integration" aria-label="Permalink to &quot;Course Integration&quot;">​</a></h2><p>LLMxRay fits naturally into:</p><ul><li><strong>Introduction to AI/ML</strong> — Understanding how language models generate text</li><li><strong>Natural Language Processing</strong> — Token analysis, embeddings, semantic similarity</li><li><strong>Software Engineering</strong> — API integration, tool calling, prompt engineering</li><li><strong>Data Science</strong> — Benchmarking methodology, statistical analysis of model outputs</li><li><strong>AI Ethics</strong> — Exploring model biases, hallucination detection, language fairness</li></ul><hr><h2 id="the-curriculum" tabindex="-1">The Curriculum <a class="header-anchor" href="#the-curriculum" aria-label="Permalink to &quot;The Curriculum&quot;">​</a></h2><h3 id="the-journey-see-→-measure-→-question-→-discover-→-build-→-contribute" tabindex="-1">The Journey: See → Measure → Question → Discover → Build → Contribute <a class="header-anchor" href="#the-journey-see-→-measure-→-question-→-discover-→-build-→-contribute" aria-label="Permalink to &quot;The Journey: See → Measure → Question → Discover → Build → Contribute&quot;">​</a></h3><p>Each module builds on the previous one. Students progress from observation to experimentation to original research.</p><table tabindex="0"><thead><tr><th>Module</th><th>Title</th><th>Duration</th><th>Difficulty</th><th>The Aha Moment</th></tr></thead><tbody><tr><td><strong>1</strong></td><td><a href="./module-1.html">What Is a Token?</a></td><td>45 min</td><td>Beginner</td><td>AI doesn&#39;t think in words — it thinks in tokens</td></tr><tr><td><strong>2</strong></td><td><a href="./module-2.html">How Does Temperature Work?</a></td><td>60 min</td><td>Beginner</td><td>Temperature isn&#39;t a linear dial — it&#39;s a phase transition</td></tr><tr><td><strong>3</strong></td><td><a href="./module-3.html">Can AI Lie?</a></td><td>90 min</td><td>Intermediate</td><td>High confidence does not mean truth</td></tr><tr><td><strong>4</strong></td><td><a href="./module-4.html">What Does the Model See?</a></td><td>45 min</td><td>Intermediate</td><td>Embeddings capture topic, not sentiment</td></tr><tr><td><strong>5</strong></td><td><a href="./module-5.html">When Does the Model Forget?</a></td><td>60 min</td><td>Intermediate</td><td>Context isn&#39;t memory — it&#39;s a sliding window</td></tr><tr><td><strong>6</strong></td><td>Can AI Use Tools?</td><td>60 min</td><td>Intermediate</td><td>Tool calling is pattern matching, not understanding</td></tr><tr><td><strong>7</strong></td><td>How Do Models Compare?</td><td>90 min</td><td>Advanced</td><td>No model is universally best</td></tr><tr><td><strong>8</strong></td><td>The Full Picture</td><td>120 min</td><td>Advanced</td><td>You can contribute to real AI research</td></tr></tbody></table><div class="info custom-block"><p class="custom-block-title">Available Modules</p><p>Modules 1 through 5 are available now. Modules 6-8 are coming soon. Each module contains hands-on exercises with LLMxRay, conceptual background grounded in published research, and assessment options.</p></div><hr><h2 id="quick-aha-moment-labs" tabindex="-1">Quick &quot;Aha Moment&quot; Labs <a class="header-anchor" href="#quick-aha-moment-labs" aria-label="Permalink to &quot;Quick &quot;Aha Moment&quot; Labs&quot;">​</a></h2><p>Standalone 15-minute exercises for any lecture — no curriculum commitment needed:</p><table tabindex="0"><thead><tr><th>Lab</th><th>The Surprise</th><th>Time</th></tr></thead><tbody><tr><td>The Hallucination Lab</td><td>Models confidently fabricate history</td><td>15 min</td></tr><tr><td>The Tokenizer Bias</td><td>Same sentence, 5x more tokens in some languages</td><td>15 min</td></tr><tr><td>The Parrot Test</td><td>Models can&#39;t repeat text verbatim — they generate, not recall</td><td>15 min</td></tr><tr><td>The System Prompt Leak</td><td>Students extract a &quot;secret&quot; system prompt</td><td>15 min</td></tr><tr><td>The Temperature Art Gallery</td><td>Same prompt at 8 temperatures displayed as a gallery</td><td>15 min</td></tr><tr><td>The Reasoning Reveal</td><td>Watch DeepSeek-R1 think step by step on a math problem</td><td>15 min</td></tr></tbody></table><p><em>Detailed guides for these labs are coming soon.</em></p><hr><h2 id="hardware-requirements" tabindex="-1">Hardware Requirements <a class="header-anchor" href="#hardware-requirements" aria-label="Permalink to &quot;Hardware Requirements&quot;">​</a></h2><h3 id="minimum-small-models-only" tabindex="-1">Minimum (small models only) <a class="header-anchor" href="#minimum-small-models-only" aria-label="Permalink to &quot;Minimum (small models only)&quot;">​</a></h3><ul><li><strong>RAM:</strong> 8 GB</li><li><strong>Storage:</strong> 10 GB free</li><li><strong>GPU:</strong> Not required (CPU inference works)</li><li><strong>Models:</strong> 1B-3B parameter models (e.g., <code>llama3.2:1b</code>)</li></ul><h3 id="recommended-for-all-modules" tabindex="-1">Recommended (for all modules) <a class="header-anchor" href="#recommended-for-all-modules" aria-label="Permalink to &quot;Recommended (for all modules)&quot;">​</a></h3><ul><li><strong>RAM:</strong> 16 GB</li><li><strong>Storage:</strong> 20 GB free</li><li><strong>GPU:</strong> 6+ GB VRAM (significantly faster inference)</li><li><strong>Models:</strong> Up to 7B-8B parameter models</li></ul><h3 id="computer-lab-setup" tabindex="-1">Computer Lab Setup <a class="header-anchor" href="#computer-lab-setup" aria-label="Permalink to &quot;Computer Lab Setup&quot;">​</a></h3><p><strong>Option A — Per-student install:</strong> Each machine runs Ollama + LLMxRay independently.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># On each machine:</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ollama</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> pull</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> llama3.2</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npx</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> llmxray</span></span></code></pre></div><p><strong>Option B — Shared Ollama server:</strong> One powerful machine runs Ollama, students connect via LLMxRay Settings.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># On the GPU server:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">OLLAMA_HOST</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">0.0.0.0</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> ollama</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> serve</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># On each student machine:</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npx</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> llmxray</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --ollama-url</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> http://gpu-server:11434</span></span></code></pre></div><p><strong>Option C — Docker deployment:</strong></p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> compose</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -f</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> docker-compose.example.yml</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> up</span></span></code></pre></div><hr><h2 id="assessment-options" tabindex="-1">Assessment Options <a class="header-anchor" href="#assessment-options" aria-label="Permalink to &quot;Assessment Options&quot;">​</a></h2><p>Each module includes multiple assessment formats. Choose based on your course:</p><table tabindex="0"><thead><tr><th>Format</th><th>Best for</th><th>Typical module</th></tr></thead><tbody><tr><td>Written reflection (300 words)</td><td>Individual, any course level</td><td>Modules 1, 4, 5</td></tr><tr><td>Data analysis table + report</td><td>Data science, NLP courses</td><td>Modules 2, 3, 7</td></tr><tr><td>Slide deck / presentation</td><td>Group work, seminars</td><td>Modules 3, 7</td></tr><tr><td>Live demo + code review</td><td>Software engineering</td><td>Module 6</td></tr><tr><td>Full research report</td><td>Advanced / capstone</td><td>Module 8</td></tr></tbody></table><hr><h2 id="getting-help" tabindex="-1">Getting Help <a class="header-anchor" href="#getting-help" aria-label="Permalink to &quot;Getting Help&quot;">​</a></h2><ul><li><strong><a href="https://github.com/LogneBudo/llmxray/discussions/categories/help" target="_blank" rel="noreferrer">GitHub Discussions — Help</a></strong> — Ask questions about setup or usage</li><li><strong><a href="https://lognebudo.github.io/llmxray/docs/en/guide/" target="_blank" rel="noreferrer">Documentation</a></strong> — Full user guide</li><li><strong><a href="https://github.com/LogneBudo/llmxray/issues/new?template=bug-report.yml" target="_blank" rel="noreferrer">Bug Reports</a></strong> — Report issues with structured templates</li></ul><hr><p><em>Using LLMxRay in your course? We&#39;d love to hear about it. Share your experience in <a href="https://github.com/LogneBudo/llmxray/discussions/categories/show-and-tell" target="_blank" rel="noreferrer">GitHub Discussions</a>.</em></p>`,40)])])}const p=e(n,[["render",i]]);export{m as __pageData,p as default};
